listitem.para:
You can edit the file "empty_driverlib_main.c" and copy the following code into it: #include"driverlib.h"
#include"device.h"

voidmain(void)
{
//
//Initializedeviceclockandperipherals
//
Device_init();

//
//InitializeGPIOandconfiguretheGPIOpinasapush-pulloutput
//
Device_initGPIO();
GPIO_setPadConfig(DEVICE_GPIO_PIN_LED1,GPIO_PIN_TYPE_STD);
GPIO_setDirectionMode(DEVICE_GPIO_PIN_LED1,GPIO_DIR_MODE_OUT);

//
//InitializePIEandclearPIEregisters.DisablesCPUinterrupts.
//
Interrupt_initModule();

//
//InitializethePIEvectortablewithpointerstotheshellInterrupt
//ServiceRoutines(ISR).
//
Interrupt_initVectorTable();

//
//EnableGlobalInterrupt(INTM)andrealtimeinterrupt(DBGM)
//
EINT;
ERTM;

//
//LoopForever
//
for(;;)
{
//
//TurnonLED
//
GPIO_writePin(DEVICE_GPIO_PIN_LED1,0);

//
//Delayforabit.
//
DEVICE_DELAY_US(500000);

//
//TurnoffLED
//
GPIO_writePin(DEVICE_GPIO_PIN_LED1,1);

//
//Delayforabit.
//
DEVICE_DELAY_US(500000);
}
}
